import numpy as np
from data import log_changes
from .base import Model, from_log

class LogEmpiricalWindowModel(Model):
    name = "log_empirical_window"
    defaults = {"window": 60}

    def predict(self, ctx, horizons):
        out = {}
        for h in horizons:
            # Use a wider window to estimate quantiles for log price changes
            ch = log_changes(ctx.hist, h, self.p["window"])
            if len(ch) < 5:
                out[h] = None
                continue
            lo, mid, hi = np.quantile(ch, [0.1, 0.5, 0.9])
            out[h] = from_log(ctx.last, lo, mid, hi)
        return out

